# Sphinx configuration for the ConicXX documentation.
#
# Build locally:  pip install -r docs/requirements.txt  (plus doxygen), then  make -C docs html
# The C++ API reference is generated by Exhale/Breathe from the public headers via Doxygen.

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

# -- Project information -----------------------------------------------------

project = "ConicXX"
author = "Jonas Breuling"
copyright = "2026, Jonas Breuling"

_cmake = (ROOT / "CMakeLists.txt").read_text()
release = re.search(r"project\(conicxx\s+VERSION\s+([0-9.]+)", _cmake).group(1)
version = release

# -- General configuration ---------------------------------------------------

extensions = [
    "sphinx.ext.mathjax",
    "sphinx.ext.githubpages",
    "sphinxcontrib.bibtex",
    "breathe",
    "exhale",
]

exclude_patterns = ["_build", "_doxygen", "design.md", "Thumbs.db", ".DS_Store"]
primary_domain = "cpp"
highlight_language = "cpp"
numfig = True
math_numfig = True
math_eqref_format = "({number})"

# -- HTML output ---------------------------------------------------------------

html_theme = "sphinx_rtd_theme"
html_title = f"ConicXX {release}"
html_static_path = ["_static"]
html_css_files = ["custom.css"]
html_theme_options = {
    "navigation_depth": 3,
    "collapse_navigation": False,
}
html_context = {
    "display_github": True,
    "github_user": "ConicXX",
    "github_repo": "ConicXX",
    "github_version": "main",
    "conf_py_path": "/docs/",
}

# -- MathJax: shorthand macros used throughout the algorithm chapters ----------

mathjax3_config = {
    "tex": {
        "macros": {
            "K": r"\mathcal{K}",
            "R": r"\mathbb{R}",
            "Q": r"\mathcal{Q}",
            "proj": r"\Pi",
            "diag": r"\operatorname{diag}",
            "inner": [r"\langle #1, #2 \rangle", 2],
        }
    }
}

# -- Bibliography --------------------------------------------------------------

bibtex_bibfiles = ["refs.bib"]
bibtex_default_style = "plain"
bibtex_reference_style = "author_year"

# -- Breathe / Exhale (C++ API reference) ----------------------------------------

breathe_projects = {"ConicXX": "./_doxygen/xml"}
breathe_default_project = "ConicXX"

_public_headers = " ".join(
    f"../src/conicxx/{h}"
    for h in ["solver.h", "settings.h", "solution.h", "cone_spec.h", "types.h", "convert.h"]
)

exhale_args = {
    "containmentFolder": "./api",
    "rootFileName": "library_root.rst",
    "doxygenStripFromPath": "..",
    "rootFileTitle": "C++ API reference",
    "createTreeView": False,
    "contentsDirectives": False,
    "exhaleExecutesDoxygen": True,
    "exhaleDoxygenStdin": f"""
        INPUT              = {_public_headers}
        STRIP_FROM_INC_PATH = ../src
        EXCLUDE_SYMBOLS    = conicxx::detail conicxx::detail::*
        EXTRACT_ALL        = YES
        MARKDOWN_SUPPORT   = YES
        WARN_IF_UNDOCUMENTED = NO
        HAVE_DOT           = NO
        CLASS_GRAPH        = NO
        COLLABORATION_GRAPH = NO
        INCLUDE_GRAPH      = NO
        INCLUDED_BY_GRAPH  = NO
        DIRECTORY_GRAPH    = NO
    """,
}
